  function message(text, error=false) { $('adminMessage').textContent=text; $('adminMessage').className='notice '+(error?'error':'success'); $('adminMessage').hidden=false; }
  function humanError(error) { const text=String(error?.message||''); return /[\u0600-\u06ff]/.test(text) ? text : 'تعذر إتمام العملية. تحقق من الاتصال وإعداد قاعدة البيانات والصلاحيات.'; }
  function badge(value) { return `<span class="badge ${[true,'active','verified','paid','completed'].includes(value)?'good':[false,'rejected','cancelled','refunded'].includes(value)?'bad':'warn'}">${esc(typeof value==='boolean'?(value?'نعم':'لا'):state(value))}</span>`; }
  function button(action,id,label,kind='') { return `<button class="btn btn-small ${kind}" data-action="${esc(action)}" data-id="${esc(id)}">${esc(label)}</button>`; }
  function empty(text) { return `<div class="empty">${esc(text)}</div>`; }
  async function action(buttonEl,callback) { if(buttonEl?.disabled)return; if(buttonEl)buttonEl.disabled=true; try{await callback();}catch(error){message(humanError(error),true);}finally{if(buttonEl)buttonEl.disabled=false;} }
  async function list(table,options={}) { return api.list(table,{limit:1000,...options}); }
