    $('editorHelp').textContent=schema.help||'';
    if(key==='tickets'&&record)$('editorHelp').textContent=record.subject+' — '+record.message;
    if(key==='renewals'&&record)$('editorHelp').textContent='الاشتراك: '+record.subscription_id+' · يتطلب التجديد ربط طلب جديد مؤكد الدفع.';
    $('editorFields').innerHTML=schema.fields.map((def,i)=>renderField(def,initial,i)).join(''); $('editorMessage').hidden=true;
    const productControl=$('editorForm').elements.namedItem('product_id'),planControl=$('editorForm').elements.namedItem('plan_id');
    if(productControl&&planControl){
      const updatePlans=()=>{const selected=planControl.value;const options=optionsFor(schema.fields.find(def=>def.key==='plan_id'),{...initial,product_id:productControl.value});planControl.innerHTML=options.map(([value,label])=>`<option value="${esc(value)}">${esc(label)}</option>`).join('');planControl.value=options.some(([value])=>value===selected)?selected:'';};
      productControl.addEventListener('change',updatePlans);updatePlans();
    }
    $('editorDialog').showModal();
