    $('sectionContent').innerHTML=`<section class="panel">${schema.help?`<p class="notice">${esc(schema.help)}</p>`:''}<div class="toolbar"><input id="adminSearch" type="search" aria-label="البحث في ${esc(schema.title)}" placeholder="ابحث في السجلات…"><div class="inline-fields"><span class="muted" id="tableCount"></span>${!schema.noCreate&&!schema.readonly?button('add','','إضافة '+schema.singular,'btn-primary'):''}${key==='products'?button('export-products','','تصدير الكتالوج')+button('import-products','','استيراد المنتجات الحالية المفقودة'):''}</div></div>${rows.length===1000?'<p class="notice warning">يعرض الجدول أول 1000 سجل. التقارير المالية تُحسب على الخادم لجميع الطلبات.</p>':''}<div class="data-region" tabindex="0" aria-label="جدول ${esc(schema.title)}"><table><thead><tr>${schema.columns.map(([,label])=>`<th>${esc(label)}</th>`).join('')}<th>الإجراءات</th></tr></thead><tbody id="tableRows"></tbody></table></div></section>`;
